<?php require_once __DIR__.'/_bootstrap.php'; if($_SERVER['REQUEST_METHOD']!=='POST')apiError('Method not allowed');verifyCsrf();$tableId=filter_var(postField('table_id'),FILTER_VALIDATE_INT);$billing=in_array(postField('billing_type'),['per_minute','per_frame','slab','challenge'],true)?postField('billing_type'):'per_minute';$walkin=sanitize(postField('player_name_walkin',''));$playerId=filter_var(postField('player_id'),FILTER_VALIDATE_INT)?:null;$challenge=max(0,(float)postField('challenge_amount',0));if(!$tableId)apiError('Choose a valid table.');$db=getDB();try{$db->beginTransaction();$q=$db->prepare('SELECT * FROM tables WHERE id=? AND club_id=? FOR UPDATE');$q->execute([$tableId,$_SESSION['club_id']]);$table=$q->fetch();if(!$table || $table['status']!=='available')throw new RuntimeException('That table is no longer available.');$stmt=$db->prepare("INSERT INTO sessions (club_id,table_id,player_id,player_name_walkin,operator_id,shift_id,start_time,billing_type,rate_plan_id,challenge_amount,status) VALUES (?,?,?,?,?,?,NOW(),?,?,?,'running')");$stmt->execute([$_SESSION['club_id'],$tableId,$playerId,$walkin?:null,$_SESSION['user_id'],activeShiftId(),$billing,$table['rate_plan_id'],$challenge]);$sessionId=(int)$db->lastInsertId();$db->prepare("UPDATE tables SET status='running' WHERE id=?")->execute([$tableId]);$db->commit();audit('session_started','sessions',$sessionId,null,['table_id'=>$tableId,'billing_type'=>$billing]);jsonResponse(true,'Session started.', ['session_id'=>$sessionId,'start_time'=>time()]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiError($e->getMessage());}
